<?php
require_once __DIR__.'/config/config.php'; require_once __DIR__.'/config/database.php'; require_once __DIR__.'/includes/functions.php';
$macId=(int)($_GET['id']??0);
$st=$pdo->prepare("SELECT m.*,t1.takim_adi ev_adi,t2.takim_adi dep_adi,g.grup_adi,h.ad hakem_ad,h.soyad hakem_soyad FROM maclar m JOIN takimlar t1 ON t1.id=m.ev_sahibi_id JOIN takimlar t2 ON t2.id=m.deplasman_id JOIN gruplar g ON g.id=m.grup_id LEFT JOIN hakemler h ON h.id=m.hakem_id WHERE m.id=?");$st->execute([$macId]);$mac=$st->fetch();
if(!$mac){http_response_code(404);exit('Maç bulunamadı.');}
$setSt=$pdo->prepare('SELECT * FROM mac_setleri WHERE mac_id=? AND tamamlandi=1 ORDER BY set_no');$setSt->execute([$macId]);$setler=$setSt->fetchAll();
$sayfa_baslik=$mac['ev_adi'].' - '.$mac['dep_adi'];$aktif='fikstur';require __DIR__.'/includes/header.php'; ?>
<main class="main-content"><section class="page-heading"><span>MAÇ MERKEZİ</span><h1><?= e($mac['ev_adi']) ?> <small>vs</small> <?= e($mac['dep_adi']) ?></h1><p><?= e($mac['grup_adi']) ?> · <?= (int)$mac['hafta'] ?>. hafta · <?= tr_tarih($mac['tarih']) ?> <?= tr_saat($mac['saat']) ?> · <?= e($mac['yer']?:'-') ?></p></section><section class="card"><div class="card-head"><h2>Canlı Set Durumu</h2><span class="badge <?= $mac['durum']==='oynandi'?'badge-ok':'' ?>"><?= $mac['durum']==='oynandi'?'Maç tamamlandı':(!empty($setler)?'Canlı skor':'Planlandı') ?></span></div><?php if(!$setler): ?><p class="muted">Henüz tamamlanan set bulunmuyor. Skorlar girildikçe burada görünür.</p><?php else: ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Set</th><th><?= e($mac['ev_adi']) ?></th><th><?= e($mac['dep_adi']) ?></th><th>Kazanan</th></tr></thead><tbody><?php foreach($setler as $s): ?><tr><td><strong><?= (int)$s['set_no'] ?>. Set</strong></td><td><?= (int)$s['ev_sahibi_set_puani'] ?></td><td><?= (int)$s['deplasman_set_puani'] ?></td><td><?= $s['ev_sahibi_set_puani']>$s['deplasman_set_puani']?e($mac['ev_adi']):($s['deplasman_set_puani']>$s['ev_sahibi_set_puani']?e($mac['dep_adi']):'Berabere') ?></td></tr><?php endforeach; ?></tbody></table></div><p><strong>Set skoru:</strong> <?= (int)$mac['ev_sahibi_set'] ?> - <?= (int)$mac['deplasman_set'] ?></p><?php endif; ?></section></main><?php if($mac['durum']==='planlandi' && $setler): ?><script>setTimeout(()=>location.reload(),15000);</script><?php endif; ?><?php require __DIR__.'/includes/sidebar.php'; require __DIR__.'/includes/footer.php'; ?>
